#include <stdexcept>
#include <string>
#include <vector>

std::size_t findIndex(const std::vector<int>& v, int value)
{
    for (std::size_t i{ 0 }; i < v.size(); ++i)
        if (v[i] == value) return i;
    return v.size();
}

std::size_t removeRange(std::vector<int>& v, std::size_t first, std::size_t last)
{
    if (first > last || last > v.size()) throw std::out_of_range("removeRange: bad range");
    v.erase(v.begin() + static_cast<std::ptrdiff_t>(first), v.begin() + static_cast<std::ptrdiff_t>(last));
    return last - first;
}

void appendAll(std::vector<std::string>& dest, const std::vector<std::string>& src, std::size_t maxTotal)
{
    if (src.size() > maxTotal || dest.size() > maxTotal - src.size()) throw std::length_error("appendAll: too many elements");
    std::vector<std::string> result;
    result.reserve(dest.size() + src.size());
    result.insert(result.end(), dest.begin(), dest.end());
    result.insert(result.end(), src.begin(), src.end());
    dest.swap(result);
}

unitTests:
TEST("finding with the past-the-end convention") {
    const std::vector<int> v{ 4, 8, 15, 16, 23, 42, 8 };
    CHECK_EQ(findIndex(v, 8), 1u);
    CHECK_EQ(findIndex(v, 42), 5u);
    CHECK_EQ(findIndex(v, 7), v.size());
    CHECK_EQ(findIndex({}, 1), 0u);
}
TEST("removing a half-open range") {
    std::vector<int> v{ 0, 1, 2, 3, 4, 5 };
    CHECK_EQ(removeRange(v, 1, 3), 2u);
    CHECK(v == (std::vector<int>{ 0, 3, 4, 5 }));
    CHECK_EQ(removeRange(v, 2, 2), 0u);
    CHECK(v == (std::vector<int>{ 0, 3, 4, 5 }));
    CHECK_EQ(removeRange(v, 0, v.size()), 4u);
    CHECK(v.empty());
    CHECK_EQ(removeRange(v, 0, 0), 0u);
}
TEST("checked preconditions leave the vector alone") {
    std::vector<int> v{ 1, 2, 3 };
    CHECK_THROWS_AS(removeRange(v, 2, 1), std::out_of_range);
    CHECK_THROWS_AS(removeRange(v, 1, 4), std::out_of_range);
    CHECK_THROWS_AS(removeRange(v, 4, 4), std::out_of_range);
    CHECK(v == (std::vector<int>{ 1, 2, 3 }));
}
TEST("appending with the strong guarantee") {
    std::vector<std::string> dest{ "a", "b" };
    appendAll(dest, { "c", "d" }, 4);
    CHECK(dest == (std::vector<std::string>{ "a", "b", "c", "d" }));
    CHECK_THROWS_AS(appendAll(dest, { "e" }, 4), std::length_error);
    CHECK(dest == (std::vector<std::string>{ "a", "b", "c", "d" }));
    appendAll(dest, {}, 4);
    CHECK_EQ(dest.size(), 4u);
}
TEST("appending a vector to itself") {
    std::vector<std::string> v{ "x", "y" };
    appendAll(v, v, 10);
    CHECK(v == (std::vector<std::string>{ "x", "y", "x", "y" }));
}
TEST("a limit that would overflow") {
    std::vector<std::string> dest{ "a" };
    CHECK_THROWS_AS(appendAll(dest, { "b", "c" }, 1), std::length_error);
    CHECK_EQ(dest.size(), 1u);
}

